args.new_string:
async function getUserPreferences() {
  try {
    // In a real app, use an environment variable for the base URL
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store',
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    return res.json();
  } catch (error) {
    console.error('Error fetching user preferences:', error);
    // Return fallback data if fetch fails
    return {
      theme: 'light',
      notifications: false,
      lastLogin: new Date().toISOString(),
    };
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div className="p-4 border rounded-lg shadow-sm">
      <h2 className="text-xl font-bold mb-4">User Dashboard</h2>
      <div className="space-y-2">
        <p><strong>Theme:</strong> {preferences.theme}</p>
        <p><strong>Notifications:</strong> {preferences.notifications ? 'On' : 'Off'}</p>
        <p><strong>Last Login:</strong> {new Date(preferences.lastLogin).toLocaleString()}</p>
      </div>
    </div>
  );
}

